const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette={'동기부여':['#8864bb','#f4effb'],'디지털스킬':['#326ac0','#edf3fc'],'소프트스킬':['#4291a4','#edf7f9'],'직무특화':['#28685e','#ecf6f1'],'공장견학':['#b67726','#fff5e7'],'문화체험':['#bc5b80','#fceff4'],'진로탐색':['#5d67aa','#f0f0fc'],'현직자특강':['#be713a','#fff2e9'],'분해조립':['#548752','#f0f7ec'],'실차체험':['#548752','#f0f7ec'],'공통행사':['#a26148','#faf0ec'],'휴일':['#82909f','#f1f3f6']};
