function lesson(e,instructors={},click=false,cid='',ending=false,extra={}){
 const name=e.instructorName||instructors[e.instructorId]?.name||'',time=e.start?`${e.start}–${e.end}`:e.hours?`${e.hours}시간 · 시각 미등록`:'';
 return `<div class="lesson-container"><${click?'button':'article'} class="lesson" style="${paint(e.module)}" ${click?`draggable="${e.kind!=='holiday'}" data-edit="${esc(e.id)}" data-cid="${esc(cid)}" aria-label="${esc(cid+'반 '+e.date+' '+e.title+' 수정')}"`:''}>${extra.changed?`<small class="changed-badge">${esc(extra.changed)}</small>`:''}<small>${esc(e.module)}${e.online?' · 비대면':''}</small><strong>${esc(e.title)}${e.day?' · '+e.day+'일차':''}</strong><small>${esc(time)}</small>${e.kind==='holiday'?'':`<small>${esc(name||'강사 미등록')}${e.venue?' · '+esc(e.venue):''}</small>`}${e.note?`<small>${esc(e.note)}</small>`:''}${extra.warn?`<small class="warn" title="${esc(extra.warn)}">⚠ ${esc(extra.warn)}</small>`:''}</${click?'button':'article'}>${(e.materials||[]).map(m=>`<a class="lecture-end" target="_blank" rel="noopener" href="${esc(materialUrl(m.url))}">자료 · ${esc(m.title)} ↗</a>`).join('')}${ending?`<a class="lecture-end survey-lesson-link" href="${esc(surveyLink(cid,e))}" target="_blank" rel="noopener">모듈 종료일, 만족도조사 필요 ↗</a>`:''}</div>`;
}
