   root.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{view=b.dataset.period;render();});$('#holidayShift').onclick=holidayDialog;$('#bulk').onclick=()=>bulkDialog();$('#weekendToggle').onchange=e=>{showWeekend=e.target.checked;render();};$('#saveTimetable').onclick=saveBoard;$('#undoMove').onclick=()=>{if(undo.length){pending=undo.pop();message='이전 이동 상태로 되돌렸습니다.';error=false;render();}};
