  let plans=[];const reset=()=>{plans=[];$('#holidayApply').disabled=true;$('#holidayResult').textContent='';$('#holidayImpact').textContent='';$('#holidayImpact').impactTicket=Symbol();};for(const id of ['holidayClass','holidayDate','holidayTitle'])$('#'+id).oninput=reset;
  $('#holidayPreview').onclick=()=>{reset();const cid=$('#holidayClass').value,day=$('#holidayDate').value,title=$('#holidayTitle').value,targets=cid==='all'?classes:classes.filter(c=>String(c.id)===cid);try{plans=targets.map(c=>({classId:String(c.id),...shiftForHoliday(data(c.id).entries,day,{title,id:'holiday-'+c.id+'-'+day})}));$('#holidayResult').innerHTML=plans.map(p=>`<details open><summary>${p.classId}반 · ${p.changes.length}개 수업 · 마지막 일정 ${p.lastDate}</summary>${p.lastDate>seed.end?'<p class="dirty">기존 교육 종료일 이후로 일정이 연장됩니다.</p>':''}</details>`).join('');const button=$('#holidayApply');void showImpact($('#holidayImpact'),plans,{note:'아래 적용은 화면의 편집본만 바꿉니다. 시간표 저장 후 공개해야 담임에게 반영됩니다.'}).then(shown=>{if(shown)button.disabled=false;});}catch(e){plans=[];$('#holidayResult').textContent=e.message;}};
