 const changed=new Map(changes.filter(c=>c.kind!=='삭제').map(c=>[c.id,changeLabel(c)])),seenKey=`hint-timetable-seen-${meta.id}`,signature=changes.length?changes[0].at+'|'+changes.length:'';
