  content.innerHTML=`<section class="today-panel"><div class="eyebrow" style="color:#bbd6f9">MY CLASS · ${esc(meta.id)}반</div><h3>오늘의 수업 <small>${todayKST().slice(5).replace('-','/')} (${weekday(todayKST())})</small></h3>${current.today.length?current.today.map(e=>card(e,ends)).join(''):`<p>${entries.length?'오늘은 예정된 수업이 없습니다.':'아직 공개된 시간표가 없습니다.'}</p>${current.next?`<div class="muted">다음 수업 · ${esc(current.next.date)} · ${esc(current.next.title)}</div>`:''}`}${changePanel()}</section><section class="teacher-calendar"><div class="top"><h2>우리 반 전체 일정</h2><span class="muted">${esc(meta.course||'')} · ${esc(meta.venue||'')}${progressText(classProgress(entries))?' · '+esc(progressText(classProgress(entries))):''}</span></div><div class="toolbar switch"><button id="week" class="${mode==='week'?'active':''}">주간</button><button id="month" class="${mode==='month'?'active':''}">월간</button><button id="previous" aria-label="이전 기간">‹</button><label>기준 날짜<input id="date" type="date" value="${date}"></label><button id="next" aria-label="다음 기간">›</button><button id="today">오늘</button><label class="inline-check"><input id="weekendToggle" type="checkbox" ${showWeekend?'checked':''}> 주말 표시</label><span class="toolbar-spacer"></span><button id="printSchedule" ${entries.length?'':'disabled'}>인쇄·PDF</button><button id="icsSchedule" ${entries.length?'':'disabled'} title="구글·네이버·아웃룩 캘린더에서 가져오기로 추가할 수 있습니다">캘린더 파일(.ics)</button></div><div class="legend">${[...new Set(entries.map(e=>e.module))].map(m=>`<span style="${paint(m)}">${esc(m)}</span>`).join('')}</div><div class="schedule-scroll"><div class="month-grid" style="grid-template-columns:repeat(${cols},minmax(125px,1fr));min-width:${cols*125}px">${days.slice(0,cols).map(d=>`<div class="grid-head">${weekday(d)}</div>`).join('')}${days.map(d=>`<div class="day-cell ${d===todayKST()?'today':''} ${mode==='month'&&d.slice(0,7)!==date.slice(0,7)?'outside':''}"><div class="day-num">${d.slice(5).replace('-','/')}</div>${entries.filter(e=>e.date===d).map(e=>card(e,ends)).join('')}</div>`).join('')}</div></div><div class="mobile-list">${all.filter(d=>entries.some(e=>e.date===d)).map(d=>`<section class="card"><h3>${d.slice(5).replace('-','/')} (${weekday(d)})</h3>${entries.filter(e=>e.date===d).map(e=>card(e,ends)).join('')}</section>`).join('')||'<div class="empty">선택한 기간의 수업이 없습니다.</div>'}</div></section>`;
